// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    // fuzzed param: arbitrary bytes _data that should be forwarded to callee by the reference
    function testFuzz_property(bytes memory data) public {
        // Deploy a helper that will REVERT unless it receives exactly the calldata we expect.
        // The helper thus differentiates between being called with the original data vs empty calldata.
        ExactCaller helper = new ExactCaller(data);

        // Try calling c.forward(helper, data) and observe whether it reverts or not.
        bool ok;
        try c.forward(address(helper), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE asserted: the reference contract forwards the exact calldata it was given.
        // Therefore, when the helper is expecting that calldata, the call should succeed (ok == true).
        // The mutant that replaces the forwarded calldata with empty bytes may cause the helper to revert,
        // producing ok == false for some inputs. We assert that the call succeeded.
        assertTrue(ok);
    }
}

// Helper that expects to be called with a specific msg.data; it reverts otherwise.
contract ExactCaller {
    bytes public expected;
    constructor(bytes memory _expected) {
        expected = _expected;
    }

    // A fallback that checks the raw calldata and reverts unless it matches `expected`.
    fallback() external payable {
        bytes memory received = msg.data;
        // Simple length and content check
        if (received.length != expected.length) {
            revert("bad calldata length");
        }
        for (uint256 i = 0; i < received.length; i++) {
            if (received[i] != expected[i]) revert("bad calldata content");
        }
        // If it matches, succeed (do nothing)
    }
}
